async (page) => {
  await page.unroute('**/game.js');
  await page.route('**/game.js', async route => {
    const response = await route.fetch();
    const body = await response.text();
    const bridge = `\nwindow.__test = { actors, enemies, evidence, riddles, villainTargets, getState:()=>({mode,storyStage,gangDown,clues,heroHealth,paused}), setStage:(stage)=>{storyStage=stage}, setClues:(n)=>{clues=n}, setGang:(n)=>{gangDown=n}, setBoss:(name)=>{boss=actors.find(a=>a.name===name);boss.health=0}, finish:()=>finishVillainMode(), villainMode:()=>villainMode(), progress:()=>progress(), collect:()=>collect(), strike:()=>strike(), setPlayer:(x,z)=>{player.position.set(x,0,z)}, setTarget:(i,x,z)=>{villainTargets[i].mesh.position.set(x,0,z)}, setAttackReady:()=>{attackCooldown=0}, getEnding:()=>({title:document.querySelector('#ending-title').textContent,copy:document.querySelector('#ending-copy').textContent}), answerRiddle:(i)=>answerRiddle(i), openRiddle:(i)=>openRiddle(riddles[i])};`;
    await route.fulfill({ response, body: body + bridge });
  });
  await page.reload();
  await page.waitForTimeout(1000);
  await page.locator('#start-button').click();
  for (let i = 0; i < 7; i++) await page.locator('#dialogue-next').click();
  await page.evaluate(() => { window.__test.setGang(5); window.__test.progress(); });
  for (let i = 0; i < 2; i++) await page.locator('#dialogue-next').click();
  await page.evaluate(() => {
    const t = window.__test;
    const clueList = t.evidence.filter(e => e.type === 'clue');
    for (const clue of clueList.slice(0, 8)) { t.setPlayer(clue.mesh.position.x, clue.mesh.position.z); t.collect(); }
  });
  const clueState = await page.evaluate(() => window.__test.getState());
  await page.locator('#dialogue-next').click();
  await page.evaluate(() => { const t = window.__test; t.setBoss('THE RIDDLER'); t.progress(); });
  const riddlerState = await page.evaluate(() => ({state:window.__test.getState(), visible:window.__test.actors.find(a=>a.name==='THE RIDDLER').mesh.visible}));
  await page.locator('#dialogue-next').click();
  await page.evaluate(() => { const t=window.__test; t.setBoss('THE RIDDLER'); t.progress(); });
  const twoFaceState = await page.evaluate(() => window.__test.getState());
  await page.evaluate(() => { const t=window.__test; t.setBoss('TWO-FACE'); t.progress(); });
  const storyEnding = await page.evaluate(() => ({state:window.__test.getState(),title:document.querySelector('#ending-title').textContent}));
  await page.locator('#replay-button').click();
  const villainStart = await page.evaluate(() => ({state:window.__test.getState(),objective:document.querySelector('#objective').textContent}));
  await page.evaluate(() => {
    const t=window.__test;
    for(let i=0;i<2;i++){
      t.setTarget(i,50,5); t.setPlayer(50,5);
      for(let hit=0;hit<6;hit++){t.setAttackReady();t.strike();}
    }
  });
  const villainEnding = await page.evaluate(() => ({state:window.__test.getState(),title:document.querySelector('#ending-title').textContent,copy:document.querySelector('#ending-copy').textContent,hidden:document.querySelector('#ending-screen').classList.contains('hidden')}));
  console.log(JSON.stringify({clueState,riddlerState,twoFaceState,storyEnding,villainStart,villainEnding},null,2));
}

