  await advanceDialogue();
  await page.evaluate(()=>{window.__test.setBoss('THE RIDDLER');window.__test.progress()});
  const riddlerState=await page.evaluate(()=>window.__test.getState());
  await advanceDialogue();
  await page.evaluate(()=>{window.__test.setBoss('THE RIDDLER');window.__test.progress()});
  const twoFaceState=await page.evaluate(()=>window.__test.getState());
  await advanceDialogue();
  await page.evaluate(()=>{window.__test.setBoss('TWO-FACE');window.__test.progress()});
  const storyEnding=await page.evaluate(()=>({state:window.__test.getState(),ending:window.__test.getEnding()}));
  await page.locator('#replay-button').click();
  const villainStart=await page.evaluate(()=>({state:window.__test.getState(),objective:document.querySelector('#objective').textContent}));
